		int a = Integer.parseInt(strArray[0]);
		int b = Integer.parseInt(strArray[1]);
		System.out.println(getGCD(a, b));

	}

	public static int getGCD(int a, int b) {
		if (a == b) return a;
		else if (a < b) {
			return getGCD(a, b - a);
		}
		else return getGCD(a - b, a);
	}
}

