                sb.append(" ").append(i);
            }
        }
        return sb.toString();
    }

    private static boolean isDiv(int n) { return n%3==0; }
    private static boolean isContain(int n) {
        String s = String.valueOf(n);
        String t = "3";
        for (int i = 0;i < s.length(); i++) {
            if (s.substring(i, i+1).equals(t)) return true;
        }
        return false;
    }
}

