		a = new long[n][m];
		b = new long[m][l];
		for (int i = 0; i < n; ++i)
		for (int j = 0; j < m; ++j) {
			a[i][j] = sc.nextLong();
		}
		for (int i = 0; i < m; ++i)
		for (int j = 0; j < l; ++j){
			b[i][j] = sc.nextLong();
		}

		r = new long[n][l];
		for (int i = 0; i < n; ++i)
		for (int j = 0; j < l; ++j) {
