				}
			}
		}

		ans = num1 + num2*6 + num3*6;

		System.out.println(ans);
	}

	public static int gcd2(int x, int y) {
		int i = x;

		while (i > 1) {
			if (x%i == 0 && y%i == 0) {
				break;
			}
			i--;
		}

		return i;
	}

	public static int gcd3(int x, int y, int z) {
		int i = x;

		while (i > 1) {
			if (x%i == 0 && y%i == 0 && z%i == 0) {
				break;
			}
			i--;
		}

		return i;
	}

}

