        while (t-- > 0) {
            solve();
        }
        long endTime = System.nanoTime();
        err.println("Execution Time : +" + (endTime - startTime) / 1000000 + " ms");
        exit(0);
    }

    static void solve() {
        long N = in.nextLong();
        long K = in.nextLong();
        out.println(Math.min(Math.floorMod(N, K), Math.abs(Math.floorMod(N, -K))));
    }

