  for(i=0;i<N;i++){
    A[i]=sc.nextInt();
  }
  for(i=0;i<N;i++){
    B[i]=sc.nextInt();
  }
  for(i=0;i<N-1;i++){
    C[i]=sc.nextInt();
  }
  sum=B[A[0]-1];
  for(i=1;i<N;i++){
    sum=sum+B[A[i]-1];
