	public static void main(String[] args) {
		FastScanner sc = new FastScanner();
		PrintWriter pw = new PrintWriter(System.out);
		char[] chars = sc.next().toCharArray();
		Arrays.sort(chars);
		if (chars[0]==chars[1] && chars[2] == chars[3] && chars[1] != chars[2]) {
