                if (i != 1) {
                    dp[i] = dp[i - 1] + dp[i - 2];
                    dp[i] %= MOD;
                } else {
                    dp[i] = dp[i - 1];
                    dp[i] %= MOD;
                }
            }
        }
        out.println(dp[N]);
