        dp[0] = 0;
        for (int i = 1; i < n; i++) {
            dp(i);            
        }
        System.out.println(dp[n-1]);
    }

    private void dp(int cur) {
        int i=0;
        if (cur <= k) {
            i = 0;
        } else {
            i = cur - k;
        }
        for(; i < cur; i++){
            dp[cur] = Math.min(dp[i] + Math.abs(h[i] - h[cur]), dp[cur]);
        }
    }
}

