        if(index>=n) return 0;
        if(memo.containsKey(index)) return memo.get(index);

        if(index+1<n) {
            long min=Integer.MAX_VALUE;
            for(int c=1;c<Math.min(n-index,k+1);c++) min=Math.min(min,Math.abs(a[index]-a[index+c])+dp(index+c));
