		if(k>=n)
			System.out.println(Math.abs(arr[n-1]-arr[0]));
		else
		{
		long memo[]=new long[n+1];
		Arrays.fill(memo, -1);
		System.out.println(mincost(arr, 0,memo,k));
		}
