import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        B3CardGameForThreeABCEdit solver = new B3CardGameForThreeABCEdit();
        solver.solve(1, in, out);
        out.close();
    }

    static class B3CardGameForThreeABCEdit {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            String[] s = in.readStringArray(3);

            int[] idx = new int[3];
            int cur = 0;
            while (true) {
                if (idx[cur] == s[cur].length()) {
                    out.printLine((char) ('A' + cur));
                    return;
                }
                cur = s[cur].charAt(idx[cur]++) - 'a';
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public String[] readStringArray(int size) {
            String[] array = new String[size];
            for (int i = 0; i < size; i++) {
                array[i] = readString();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public String readString() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                if (Character.isValidCodePoint(c)) {
                    res.appendCodePoint(c);
                }
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void printLine(char i) {
            writer.println(i);
        }

        public void close() {
            writer.close();
        }

    }
}

import java.util.ArrayDeque;
import java.util.Queue;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        Main m = new Main(sc);
        m.show(m.solve());
        sc.close();
    }

	//フィールド
    Scanner sc;
    Queue<String> A = new ArrayDeque<String>();
    Queue<String> B = new ArrayDeque<String>();
    Queue<String> C = new ArrayDeque<String>();
    char next = 'a';

    //入力
    Main(Scanner sc) {
        this.sc = sc;
        this.A = read();
        this.B = read();
        this.C = read();
    }

    //キューに値を格納するためのメソッド
    private Queue<String> read() {
    	Queue<String> tmp = new ArrayDeque<String>();
    	String S = sc.next();
    	for (int i=0; i<S.length(); i++) {
    		tmp.add(String.valueOf(S.charAt(i)));
    	}
    	return tmp;
    }

    //解答処理
    private String solve() {
        String answer = null;

        while (true) {
        	if (next == 'a') {
        		if (A.size() == 0) {
            		answer = "A";
            		break;
            	}
        		play(A);
        	} else if (next == 'b') {
        		if (B.size() == 0) {
            		answer = "B";
            		break;
            	}
        		play(B);
        	} else if (next == 'c') {
        		if (C.size() == 0) {
            		answer = "C";
            		break;
            	}
        		play(C);
        	}

        }

        return answer;
    }

    //操作
    private Queue<String> play(Queue<String> tmp) {
    	next = tmp.poll().charAt(0);
    	return tmp;
    }

    //出力
    public void show(String answer) {
        System.out.println(answer);
    }

}

